(3844974, 544036, 63537, '<td valign="top">Title fits the photo nicely. Very fun :)</td>', 'Title fits the photo nicely. Very fun :)', '2007-06-28 11:11:44.000000', NULL, 1),
(3845035, 543797, 80259, '<td valign="top">In my opinion the super grainy noisy effect is horribly distracting.  It detracts so much from what is otherwise a nicely composed image.</td>', 'In my opinion the super grainy noisy effect is horribly distracting.  It detracts so much from what is otherwise a nicely composed image.', '2007-06-28 11:34:15.000000', NULL, 1),
