(3846953, 541106, 79681, '<td valign="top">You might not want to add such a lone title. Maybe for this one something short and sweet to allow the viewer to be creative. I love the Tones in this photo. I also love the whole vintage theme going on. Makes me wonder if a place like this really exists. The Vintage cap with the flower, shirt and tie with cuffs. The expression on his face is a good one.</td>', 'You might not want to add such a lone title. Maybe for this one something short and sweet to allow the viewer to be creative. I love the Tones in this photo. I also love the whole vintage theme going on. Makes me wonder if a place like this really exists. The Vintage cap with the flower, shirt and tie with cuffs. The expression on his face is a good one.', '2007-06-28 23:55:36.000000', NULL, 1),
(3846962, 542623, 79681, '<td valign="top">Very creative... not artsy. But still. Its true, that is "solo".</td>', 'Very creative... not artsy. But still. Its true, that is "solo".', '2007-06-28 23:57:14.000000', NULL, 1),
(3846976, 541071, 79681, '<td valign="top">I had to take a second look at this. Is this really a tear drop?? anyways. I dont know if it would be considered as "solo" but. I like it. its very creative. Good job!</td>', 'I had to take a second look at this. Is this really a tear drop?? anyways. I dont know if it would be considered as "solo" but. I like it. its very creative. Good job!', '2007-06-28 23:59:54.000000', NULL, 1),
(3846979, 543900, 76430, '<td valign="top">I don''t understand the picture and title.  I don''t see a girl, this isn''t Ipanema, and it just looks like a picture of a weedy canal.  Sorry, but it doesn''t do anything for me.</td>', 'I don''t understand the picture and title.  I don''t see a girl, this isn''t Ipanema, and it just looks like a picture of a weedy canal.  Sorry, but it doesn''t do anything for me.', '2007-06-29 00:00:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3846980, 543981, 12796, '<td valign="top">the background is quite distracting which draws back attention from the main subject. I fear that this might be due to serious lack of features in camera. a part of the log appears to be a bit overexposed to me in my laptop screen. a little more zoom would have eliminated this, and would have made the background more blurry... if your camera has got a digital zoom only or a very limited optical zoom, use digital zoom effectively.. i''ve read one excellent tutorial in DPC tutorials page titled something like cheap enhancements for your digital camera.</td>', 'the background is quite distracting which draws back attention from the main subject. I fear that this might be due to serious lack of features in camera. a part of the log appears to be a bit overexposed to me in my laptop screen. a little more zoom would have eliminated this, and would have made the background more blurry... if your camera has got a digital zoom only or a very limited optical zoom, use digital zoom effectively.. i''ve read one excellent tutorial in DPC tutorials page titled something like cheap enhancements for your digital camera.', '2007-06-29 00:00:34.000000', NULL, 1),
(3847015, 543937, 12796, '<td valign="top">one humble advice.. please avoid using your in-camera forced flash unless until you are looking for a snapshot alone. your performer looks a bit scary with those red eyes (when shooting people in low light conditions, use a fill flash or atleast use red eye reduction).</td>', 'one humble advice.. please avoid using your in-camera forced flash unless until you are looking for a snapshot alone. your performer looks a bit scary with those red eyes (when shooting people in low light conditions, use a fill flash or atleast use red eye reduction).', '2007-06-29 00:09:24.000000', NULL, 1),
(3847022, 543308, 23394, '<td valign="top">damn shame this challenge came after season end :(<br/> <br/>as always, exquisite.</td>', 'damn shame this challenge came after season end :( as always, exquisite.', '2007-06-29 00:10:36.000000', NULL, 1),
(3847044, 543637, 12796, '<td valign="top">excellent photo. i really liked the idea of no colour in this one. solitude is a theme which works well this way. good framing, but somehow i feel like the cropping is not right. 6</td>', 'excellent photo. i really liked the idea of no colour in this one. solitude is a theme which works well this way. good framing, but somehow i feel like the cropping is not right. 6', '2007-06-29 00:15:22.000000', NULL, 1),
(3847053, 544012, 12796, '<td valign="top">it is a sad thing that the boy is not completely in focus, and the overexposed table is a bit distracting.</td>', 'it is a sad thing that the boy is not completely in focus, and the overexposed table is a bit distracting.', '2007-06-29 00:17:21.000000', NULL, 1),
