(3851131, 542438, 7485, '<td valign="top">Very good lighting, but the on-the-heels pose seems forced and strange to me. And her expression doesn''t particularly say "lonely"</td>', 'Very good lighting, but the on-the-heels pose seems forced and strange to me. And her expression doesn''t particularly say "lonely"', '2007-06-30 12:38:00.000000', NULL, 1),
(3851136, 543300, 7485, '<td valign="top">Great composition! Make yourself an ''advanced editing'' version where you remove the cone and leg in the background, and you''ll have a killer photo for your portfolio.</td>', 'Great composition! Make yourself an ''advanced editing'' version where you remove the cone and leg in the background, and you''ll have a killer photo for your portfolio.', '2007-06-30 12:40:40.000000', NULL, 1),
(3851140, 540593, 7485, '<td valign="top">You need to shift the black-point to increase the contrast, there''s nothing even close to black in the image (and consequently it looks washed out)</td>', 'You need to shift the black-point to increase the contrast, there''s nothing even close to black in the image (and consequently it looks washed out)', '2007-06-30 12:43:46.000000', NULL, 1),
(3851142, 541106, 7485, '<td valign="top">Normally I''m not a fan of this much ''grunge'', but I have to admit it almost works for this otherwise excellent image</td>', 'Normally I''m not a fan of this much ''grunge'', but I have to admit it almost works for this otherwise excellent image', '2007-06-30 12:45:48.000000', NULL, 1),
