(3851150, 541519, 7485, '<td valign="top">Cute expression, but the post-processing has problems. There are jaggies/pixelation around the eyes and what looks like compression artifacts around the outline of the shoulder.</td>', 'Cute expression, but the post-processing has problems. There are jaggies/pixelation around the eyes and what looks like compression artifacts around the outline of the shoulder.', '2007-06-30 12:51:50.000000', NULL, 1),
(3851157, 544222, 7485, '<td valign="top">Good idea, but the frame''s gotta go. Also, I think the composition would be stronger with less foreground clutter, cropping somewhere around the lower balcony.</td>', 'Good idea, but the frame''s gotta go. Also, I think the composition would be stronger with less foreground clutter, cropping somewhere around the lower balcony.', '2007-06-30 13:00:08.000000', NULL, 1),
(3851161, 540313, 7485, '<td valign="top">I think you''ve gone over the top with the contrast here, especially with the large solid-black foreground.</td>', 'I think you''ve gone over the top with the contrast here, especially with the large solid-black foreground.', '2007-06-30 13:03:54.000000', NULL, 1),
(3851169, 542306, 35613, '<td valign="top">I wish the flower had more light on it.</td>', 'I wish the flower had more light on it.', '2007-06-30 13:08:40.000000', NULL, 1),
