INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3851511, 543819, 76430, '<td valign="top">Sorry, but I don''t get it.  It looks like a manhole cover with a piece of paper, maybe a musical composition on it?</td>', 'Sorry, but I don''t get it.  It looks like a manhole cover with a piece of paper, maybe a musical composition on it?', '2007-06-30 16:39:37.000000', NULL, 1),
(3851512, 542637, 76430, '<td valign="top">Good diagonal capture making the trumpet horizontal.</td>', 'Good diagonal capture making the trumpet horizontal.', '2007-06-30 16:40:40.000000', NULL, 1),
(3851516, 543040, 76430, '<td valign="top">I don''t think the negative image helps this.  It would have been better as a positive.</td>', 'I don''t think the negative image helps this.  It would have been better as a positive.', '2007-06-30 16:44:25.000000', NULL, 1),
(3851530, 543683, 76430, '<td valign="top">This is an emotional image portrayed as a group of 4 alone, whether it''s staged or not.  Stark background, clinging to what little they have, alone and scared.  Good picture.</td>', 'This is an emotional image portrayed as a group of 4 alone, whether it''s staged or not.  Stark background, clinging to what little they have, alone and scared.  Good picture.', '2007-06-30 16:51:30.000000', NULL, 1),
(3851616, 543517, 76430, '<td valign="top">Very nice, almost like digital art, but well done in basic.  9</td>', 'Very nice, almost like digital art, but well done in basic.  9', '2007-06-30 17:43:13.000000', NULL, 1),
(3851624, 540303, 76430, '<td valign="top">I am guessing the solo and the "My" in the title is the person on the boat, or is it you?  It''s too washed out and the boat is crowding the left edge too much.</td>', 'I am guessing the solo and the "My" in the title is the person on the boat, or is it you?  It''s too washed out and the boat is crowding the left edge too much.', '2007-06-30 17:49:08.000000', NULL, 1),
(3851627, 541285, 76430, '<td valign="top">I love the expression.  The cone and dress are somewhat washed out and the shingle siding and white post don''t help, but overall it''s great.</td>', 'I love the expression.  The cone and dress are somewhat washed out and the shingle siding and white post don''t help, but overall it''s great.', '2007-06-30 17:51:29.000000', NULL, 1),
(3851924, 541769, 76430, '<td valign="top">Great DOF, angle, coloring.  It''s a bit blown out in a couple of places, but very good. What''s with the depressed key, is it broken, wedged, or did you press it and move your finger away that quickly?  It does indicate a single note to go with the theme.</td>', 'Great DOF, angle, coloring.  It''s a bit blown out in a couple of places, but very good. What''s with the depressed key, is it broken, wedged, or did you press it and move your finger away that quickly?  It does indicate a single note to go with the theme.', '2007-06-30 21:57:59.000000', NULL, 1),
(3852039, 543430, 54431, '<td valign="top">This shot made me smile! :-) Great job! I absolutely love everything about it. The person running with their hands up seems so carefree and their silhouette is amazing. The sky is gorgeous and I like that you decided to keep it as the main focus. 10!</td>', 'This shot made me smile! :-) Great job! I absolutely love everything about it. The person running with their hands up seems so carefree and their silhouette is amazing. The sky is gorgeous and I like that you decided to keep it as the main focus. 10!', '2007-06-30 23:28:55.000000', NULL, 1),
(3852611, 544237, 19952, '<td valign="top">People have probably already told you, but it''s actually Thoth. And yes, he''s definitely one of a kind. :-)</td>', 'People have probably already told you, but it''s actually Thoth. And yes, he''s definitely one of a kind. :-)', '2007-07-01 03:01:55.000000', NULL, 1),
(3852688, 542030, 15511, '<td valign="top">The lad should be wearing gloves and eye protection.</td>', 'The lad should be wearing gloves and eye protection.', '2007-07-01 03:26:45.000000', NULL, 1),
